import { defineConfig } from "orval";

// Plain header for generated files (the default one contains an emoji).
const header = (info: { title?: string; version?: string }) => [
  "Generated by Orval from openapi/api-spec.json. Do not edit by hand.",
  `${info.title ?? "API"} ${info.version ?? ""}`.trim(),
];

// Generates the typed API client from openapi/api-spec.json.
// Output in src/lib/api/generated is never edited by hand: change the spec
// (npm run api:sync) and run npm run api:gen instead.
export default defineConfig({
  api: {
    input: { target: "./openapi/api-spec.json" },
    output: {
      mode: "tags-split",
      target: "./src/lib/api/generated/endpoints",
      schemas: "./src/lib/api/generated/model",
      client: "react-query",
      httpClient: "fetch",
      clean: true,
      formatter: "prettier",
      override: {
        header,
        mutator: {
          path: "./src/lib/api/fetcher.ts",
          name: "apiFetch",
        },
        fetch: {
          includeHttpResponseReturnType: false,
        },
        query: {
          version: 5,
          useQuery: true,
          useSuspenseQuery: true,
          signal: true,
        },
      },
    },
  },
  apiZod: {
    input: { target: "./openapi/api-spec.json" },
    output: {
      mode: "tags-split",
      target: "./src/lib/api/generated/zod",
      client: "zod",
      fileExtension: ".zod.ts",
      clean: true,
      formatter: "prettier",
      override: { header },
    },
  },
});
